/*
 * Foxiru (OC) - animated, pixel-traced from the original art (2000x2000 source, 41-colour palette).
 *
 * Every colour region of the art is a vector path in source coordinates, grouped into rigid parts:
 *   shadow | tail | body | forearm+paw | head | 2 ears | 2 hair tufts | per-eye (sclera, iris, outline)
 * Parts are drawn back to front and animated with small rotations about joint pivots, so the
 * silhouette, palette and linework stay identical to the PNG at rest.
 *
 * Usage (behind any screen):
 *     Box(Modifier.fillMaxSize()) {
 *         FoxiruOCBackground(Modifier.fillMaxSize())
 *         /* your gallery content, with transparent containers */
 *     }
 */

/** Drop-in animated background. [scale] 1f fits the whole figure into the box; [alignment] places it. */
@Composable
fun FoxiruOCBackground(
    modifier: Modifier = Modifier,
    alpha: Float = 1f,
    alignment: Alignment = Alignment.BottomEnd,
    scale: Float = 1f,
    animated: Boolean = true,
) {
    val model by produceState<FoxiruOCModel?>(null) {
        value = withContext(Dispatchers.Default) { FoxiruOCModel.get() }
    }
    val ctx = LocalContext.current
    // honour "Remove animations" / animator scale 0
    val motionOff = remember(ctx) {
        Settings.Global.getFloat(ctx.contentResolver, Settings.Global.ANIMATOR_DURATION_SCALE, 1f) == 0f
    }
    val running = animated && !motionOff
    val clock = remember { mutableFloatStateOf(0f) }
    LaunchedEffect(running) {
        if (running) {
            val t0 = withFrameMillis { it }
            while (true) withFrameMillis { clock.floatValue = (it - t0) / 1000f }
        }
    }
    Canvas(
        modifier.graphicsLayer {
            this.alpha = alpha
            compositingStrategy = if (alpha < 1f) CompositingStrategy.Offscreen else CompositingStrategy.Auto
        },
    ) {
        val m = model ?: return@Canvas
        // clock is read here (draw phase) -> redraws only, no recomposition per frame
        val pose = if (running) foxiruPoseAt(clock.floatValue) else FoxiruPose.Rest
        val b = FoxiruOCModel.Bounds
        val fit = min(size.width / b.width, size.height / b.height) * scale
        val box = IntSize((b.width * fit).roundToInt(), (b.height * fit).roundToInt())
        val at = alignment.align(box, IntSize(size.width.roundToInt(), size.height.roundToInt()), layoutDirection)
        withTransform({
            translate(at.x - b.left * fit, at.y - b.top * fit)
            scale(fit, fit, Offset.Zero)
        }) { m.draw(this, pose) }
    }
}

/** One frame of Foxiru's skeleton. Angles in degrees, offsets in source pixels. */
class FoxiruPose(
    val breath: Float,   // -1..1, drives body squash/stretch (feet stay planted) + shadow
    val tail: Float,
    val forearm: Float,
    val head: Float,
    val headDy: Float,
    val earL: Float,
    val earR: Float,
    val tuftL: Float,
    val tuftR: Float,
    val gazeX: Float,
    val gazeY: Float,
    val blink: Float,    // eye height scale, 1 = open
) {
    companion object {
        val Rest = FoxiruPose(0f, 0f, 0f, 0f, 0f, 0f, 0f, 0f, 0f, 0f, 0f, 1f)
    }
}

private const val TAU = 6.2831855f
private fun smooth(a: Float, b: Float, x: Float): Float { val k = ((x - a) / (b - a)).coerceIn(0f, 1f); return k * k * (3f - 2f * k) }
private fun bump(p: Float, start: Float, dur: Float): Float = if (p in start..(start + dur)) sin(Math.PI.toFloat() * (p - start) / dur) else 0f
private fun flick(p: Float, amp: Float, len: Float = 0.55f): Float = if (p < len) { val k = p / len; amp * sin(k * TAU * 1.5f) * (1f - k) } else 0f
private val Gaze = arrayOf(0f to 0f, -16f to 9f, -5f to -6f, 13f to 7f, 0f to 0f, -12f to -3f)

/** Idle loop: breathing, tail wag, periodic hello-wave, head sway, ear flicks, blinks, glances. */
fun foxiruPoseAt(t: Float): FoxiruPose {
    val w = TAU / 3.4f
    val breath = sin(w * t)
    val lag = sin(w * t - 0.7f)
    val tail = 3.6f * sin(TAU * t / 2.6f) + 1.0f * sin(TAU * t / 1.1f + 1f)

    val wp = t % 7.0f                                   // wave 3s out of every 7s
    val env = smooth(0.6f, 1.0f, wp) * (1f - smooth(3.0f, 3.6f, wp))
    val forearm = env * 9f * sin(TAU * 1.5f * (wp - 0.6f)) + (1f - env) * 1.2f * sin(w * t + 0.5f)

    val head = 1.4f * lag + 0.8f * sin(TAU * t / 7.1f)
    val earFollow = 1.6f * sin(w * t - 1.2f)
    val earR = earFollow + flick((t + 4.1f) % 6.1f, 5f)
    val earL = -earFollow + flick((t + 3.3f) % 8.3f, -4.5f)
    val tuft = 2.2f * sin(w * t - 1.6f)

    val blinkClosed = maxOf(bump(t % 4.3f, 4.0f, 0.2f), bump(t % 9.7f, 9.3f, 0.18f))
    val gi = (t / 2.6f).toInt(); val gk = smooth(2.15f, 2.6f, t % 2.6f)
    val g0 = Gaze[gi % Gaze.size]; val g1 = Gaze[(gi + 1) % Gaze.size]

    return FoxiruPose(
        breath = breath, tail = tail, forearm = forearm, head = head, headDy = -3f * lag,
        earL = earL, earR = earR, tuftL = tuft, tuftR = -tuft,
        gazeX = g0.first + (g1.first - g0.first) * gk, gazeY = g0.second + (g1.second - g0.second) * gk,
        blink = 1f - 0.92f * blinkClosed,
    )
}

/** Parsed vector parts of Foxiru. Built once, off the main thread, then shared. */
class FoxiruOCModel private constructor() {
    private class Region(val color: Color, val path: Path)
    private class Eye(val center: Offset, val base: Region, val cyan: Region, val iris: List<Region>, val ring: List<Region>)

    private fun layer(rows: Array<Pair<String, String>>): List<Region> = rows.map { (hex, d) ->
        Region(
            Color(0xFF000000L or hex.toLong(16)),
            PathParser().parsePathString(d).toPath().apply { fillType = PathFillType.EvenOdd },
        )
    }

    private val shadow = layer(FoxiruPaths.shadow)
    private val tail = layer(FoxiruPaths.tail)
    private val body = layer(FoxiruPaths.body)
    private val forearm = layer(FoxiruPaths.forearm)
    private val head = layer(FoxiruPaths.head)
    private val earL = layer(FoxiruPaths.earL)
    private val earR = layer(FoxiruPaths.earR)
    private val tuftL = layer(FoxiruPaths.tuftL)
    private val tuftR = layer(FoxiruPaths.tuftR)
    private val eyes = listOf(
        Eye(Offset(961f, 654f), layer(FoxiruPaths.eyeLBase)[0], layer(FoxiruPaths.eyeLCyan)[0], layer(FoxiruPaths.eyeLIris), layer(FoxiruPaths.eyeLRing)),
        Eye(Offset(1236f, 622f), layer(FoxiruPaths.eyeRBase)[0], layer(FoxiruPaths.eyeRCyan)[0], layer(FoxiruPaths.eyeRIris), layer(FoxiruPaths.eyeRRing)),
    )
    private val shadowPivot = shadow.first().path.getBounds().center

    private fun DrawScope.fill(l: List<Region>) { for (r in l) drawPath(r.path, r.color) }

    fun draw(scope: DrawScope, p: FoxiruPose) = with(scope) {
        withTransform({ scale(1f - 0.015f * p.breath, 1f, shadowPivot) }) { fill(shadow) }

        val sy = 1f + 0.010f * p.breath                       // body space: squash/stretch about the feet
        withTransform({ scale(2f - sy, sy, Feet) }) {
            withTransform({ rotate(p.tail, TailPivot) }) {
                drawRect(TailFill, Offset(945f, 1250f), Size(70f, 550f))   // hidden root, keeps tail joined to the leg
                fill(tail)
            }
            fill(body)
            drawRect(NeckFill, Offset(1086f, 856f), Size(76f, 24f))        // hidden neck, keeps head joined to the body
            withTransform({ rotate(p.forearm, ElbowPivot) }) { fill(forearm) }

            withTransform({ translate(0f, p.headDy); rotate(p.head, NeckPivot) }) {
                fill(head)
                drawRect(FaceFill, Offset(1296f, 505f), Size(44f, 75f))        // hidden cheek, keeps ear/tuft seam closed
                for (e in eyes) {
                    withTransform({ scale(1f, p.blink, e.center) }) {
                        drawPath(e.base.path, e.base.color)
                        drawPath(e.cyan.path, e.cyan.color)
                        clipPath(e.base.path) { withTransform({ translate(p.gazeX, p.gazeY) }) { fill(e.iris) } }
                        fill(e.ring)
                    }
                }
                withTransform({ rotate(p.earL, EarLPivot) }) { fill(earL) }
                withTransform({ rotate(p.earR, EarRPivot) }) { fill(earR) }
                withTransform({ rotate(p.tuftL, TuftLPivot) }) { fill(tuftL) }
                withTransform({ rotate(p.tuftR, TuftRPivot) }) { fill(tuftR) }
            }
        }
    }

    companion object {
        /** Figure bounds in source (2000x2000) coordinates, with room for the animation. */
        val Bounds = Rect(320f, 20f, 1592f, 1992f)

        private val Feet = Offset(1010f, 1880f)
        private val TailPivot = Offset(958f, 1560f)
        private val ElbowPivot = Offset(870f, 1140f)
        private val NeckPivot = Offset(1100f, 872f)
        private val EarLPivot = Offset(900f, 445f)
        private val EarRPivot = Offset(1235f, 430f)
        private val TuftLPivot = Offset(870f, 740f)
        private val TuftRPivot = Offset(1330f, 700f)
        private val TailFill = Color(0xFFFF7D3F)
        private val NeckFill = Color(0xFFFFAC53)
        private val FaceFill = Color(0xFFFFAC53)

        @Volatile private var cached: FoxiruOCModel? = null
        fun get(): FoxiruOCModel = cached ?: synchronized(this) { cached ?: FoxiruOCModel().also { cached = it } }
    }
}

